import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export interface NodeConfig {
  imageUrl?: string;
  depthMapUrl?: string;
  meshUrl?: string;
  textContent?: Array<{
    text: string;
    role?: string;
    typography?: {
      fontSize?: number;
      color?: string;
      align?: 'left' | 'center' | 'right';
      maxWidthPx?: number;
      letterSpacingPx?: number;
    };
  }>;
  intent?: {
    visualSpec?: {
      textContent?: NodeConfig['textContent'];
      colors?: Record<string, string>;
    };
  };
  cinematicPrimitives?: Array<{
    name: string;
    params?: Record<string, unknown>;
    trigger?: string;
  }>;
  scenePosition?: {
    position?: [number, number, number];
    rotation?: [number, number, number];
    scale?: [number, number, number];
  };
}

export interface NodeContext {
  THREE: any;
  textureLoader: {
    loadTexture(url: string): Promise<any>;
  };
  glbLoader: {
    loadGLB(url: string): Promise<any>;
  };
  videoLoader?: {
    loadVideo(url: string): Promise<any>;
  };
  fontAtlas: {
    createText(content: string, opts?: Record<string, unknown>): any;
  };
  primitives: Record<
    string,
    (target: any, params?: Record<string, unknown>) => {
      timeline?: any;
      cleanup?: () => void;
    }
  >;
  emit(event: string, payload?: unknown): void;
  tier?: 'T0' | 'T1' | 'T2';
}

export default function createNode(config: NodeConfig, ctx: NodeContext): any {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CircleGeometry,
    Object3D,
    Color,
    Vector3,
    PointLight,
  } = ctx.THREE;

  const root = new Group();
  const timelines: any[] = [];
  const primitiveCleanups: Array<() => void> = [];
  const resources: any[] = [];
  let disposed = false;

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
    ...(config.intent?.visualSpec?.colors ?? {}),
  };

  root.userData = root.userData ?? {};
  root.userData.role = 'pricing-quote-panel';
  root.userData.colors = colors;

  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropY = uv().y;
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.090, 0.090, 0.114),
      smoothstep(0.35, 0.78, backdropY)
    ),
    smoothstep(0.0, 1.0, backdropY)
  );

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial
  );
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  });
  const contactShadow = new Mesh(
    new CircleGeometry(2.15, 64),
    shadowMaterial
  );
  contactShadow.scale.set(1.45, 0.42, 1);
  contactShadow.position.set(0, -1.12, -0.34);
  root.add(contactShadow);
  resources.push(contactShadow.geometry, contactShadow.material);

  const cardGroup = new Group();
  cardGroup.position.set(0, 0, 0.08);
  root.add(cardGroup);

  const cardMaterial = new MeshStandardNodeMaterial({
    color: colors.paper,
    roughness: 0.62,
    metalness: 0.24,
    transparent: true,
  });

  const card = new Mesh(
    new PlaneGeometry(3.25, 2.05),
    cardMaterial
  );
  cardGroup.add(card);
  resources.push(card.geometry, card.material);

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0,
    depthWrite: false,
  });

  const topEdge = new Mesh(
    new PlaneGeometry(3.08, 0.035),
    edgeMaterial
  );
  topEdge.position.set(0, 0.985, 0.035);
  cardGroup.add(topEdge);

  const sideEdge = new Mesh(
    new PlaneGeometry(0.035, 1.72),
    edgeMaterial
  );
  sideEdge.position.set(1.575, -0.08, 0.036);
  cardGroup.add(sideEdge);

  resources.push(topEdge.geometry, sideEdge.geometry, edgeMaterial);

  const accentCoreMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.9,
  });
  const accentCore = new Mesh(
    new PlaneGeometry(0.16, 0.16),
    accentCoreMaterial
  );
  accentCore.position.set(-1.35, -0.72, 0.05);
  cardGroup.add(accentCore);
  resources.push(accentCore.geometry, accentCore.material);

  const key = new PointLight(colors.paper, 1.05, 7, 2);
  key.position.set(-2.2, 2.4, 2.6);
  root.add(key);

  const rim = new PointLight(colors.accent, 0.72, 5, 2);
  rim.position.set(2.4, -0.4, 1.7);
  root.add(rim);

  const fill = new PointLight(colors.paper, 0.3, 5, 2);
  fill.position.set(0, -1.7, 1.8);
  root.add(fill);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture: any) => {
      if (disposed) {
        texture?.dispose?.();
        return;
      }
      if ('colorSpace' in texture && ctx.THREE.SRGBColorSpace) {
        texture.colorSpace = ctx.THREE.SRGBColorSpace;
      }
      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    cardGroup.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.34, ease: 'power3.out' }
  ).to(cardGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.56,
    ease: 'power4.out',
  }, '>-0.02');
  timelines.push(entrance);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const text = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.typography?.color ?? colors.ink,
      align: item.typography?.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx,
    });
    cardGroup.add(text);
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    }
  }

  const hoverLift = gsap.quickTo(cardGroup.position, 'y', {
    duration: 0.3,
    ease: 'power2.out',
  });
  const hoverTilt = gsap.quickTo(cardGroup.rotation, 'z', {
    duration: 0.3,
    ease: 'power2.out',
  });

  root.userData.handlers = {
    hover: (active = true) => {
      hoverLift(active ? 0.15 : 0);
      hoverTilt(active ? -0.025 : 0);
      gsap.to(edgeMaterial, {
        opacity: active ? 1 : 0,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    click: () => {
      const press = gsap.timeline();
      press.to(cardGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
      }).to(cardGroup.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.42,
        ease: 'back.out(2)',
      });
      timelines.push(press);
      ctx.emit('hub-pricing.select', { node: root });
    },
    focus: (active = true) => {
      gsap.to(edgeMaterial, {
        opacity: active ? 1 : 0,
        duration: 0.2,
        ease: 'power2.out',
      });
    },
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    root.traverse((object: any) => {
      object.geometry?.dispose?.();

      const material = object.material;
      if (Array.isArray(material)) {
        material.forEach((entry) => entry?.dispose?.());
      } else {
        material?.dispose?.();
      }
    });

    for (const resource of resources) {
      if (resource !== root && resource?.dispose) resource.dispose();
    }

    root.clear();
  };

  return root;
}
